INSERT INTO projects (id, name, status, start_date, target_date, target_budget, description, version, created_at, modified_at) VALUES
(1, '다온뱅크 여신 시스템 고도화', 'ONGOING', '2026-01-06', '2026-11-30', 1200000000, '다온뱅크 여신본부 요청으로 착수. 기존 여신 심사 시스템의 처리 속도가 느리고 화면 UX가 낡아 심사 담당자들의 불만이 누적돼 있었다. 심사 처리 시간을 단축하고 자동 심사 비중을 확대해 심사역 1인당 처리 건수를 늘리는 것이 목표.', 0, '2026-01-06 09:00:00', '2026-08-06 18:00:00'),
(2, '다온증권 해외주식 주문 개선', 'ONGOING', '2026-03-02', '2026-10-31', 500000000, '다온증권 해외주식 서비스의 주문 처리 지연과 환율 표시 오차에 대한 고객 불만이 반복 접수돼 착수. 주문 처리 파이프라인을 개선하고 실시간 환율 연동 안정성을 높이는 것이 목표.', 0, '2026-03-02 09:00:00', '2026-08-06 18:00:00'),
(3, '다온페이 정산 배치 재구축', 'ONGOING', '2026-05-04', '2027-01-31', 450000000, '다온페이 정산 배치가 반복적으로 실패해 익일 정산이 지연되는 문제가 발생, 원인이 된 레거시 배치 로직을 전면 재구축하기로 결정했다. 안정적인 야간 정산 처리와 장애 재발 방지가 목표.', 0, '2026-05-04 09:00:00', '2026-08-06 18:00:00'),
(4, '한빛저축은행 코어뱅킹 컨설팅', 'ONGOING', '2026-06-01', '2026-12-31', 300000000, '한빛저축은행으로부터 코어뱅킹 시스템 현대화 컨설팅을 의뢰받아 수주. 현행 시스템 진단과 개선 로드맵 수립이 1차 목표이며, 결과에 따라 후속 구축 사업으로 이어질 수 있다.', 0, '2026-06-01 09:00:00', '2026-08-06 18:00:00'),
(5, '서일캐피탈 여신심사 시스템 구축', 'ONGOING', '2026-02-03', '2027-03-31', 900000000, '서일캐피탈이 수기 중심이던 여신심사 프로세스를 디지털 전환하고 싶다는 요청으로 수주. 심사 데이터를 시스템화해 처리 속도와 심사 정확도를 동시에 높이는 것이 목표.', 0, '2026-02-03 09:00:00', '2026-08-06 18:00:00'),
(6, '마이데이터 3.0 대응', 'ONGOING', '2026-04-01', '2027-02-28', 400000000, '금융위원회의 마이데이터 3.0 규격 시행이 확정되면서 대응이 불가피해져 착수한 필수 규제 대응 프로젝트. 신규 데이터 표준과 전송 방식을 반영해 시행일 전까지 대응을 완료하는 것이 목표.', 0, '2026-04-01 09:00:00', '2026-08-06 18:00:00'),
(7, 'FDS 엔진 v3', 'ONGOING', '2026-03-16', '2026-12-31', 350000000, '기존 FDS 엔진(v2)의 탐지 정확도가 신종 사기 패턴을 따라가지 못한다는 문제 제기로 착수. 오탐률을 낮추고 실시간 이상거래 탐지 정확도를 높이는 것이 목표.', 0, '2026-03-16 09:00:00', '2026-08-06 18:00:00'),
(8, 'ISMS-P 인증 갱신', 'ONGOING', '2026-07-01', '2026-10-31', 150000000, '기존 ISMS-P 인증 유효기간 만료가 다가와 갱신 심사를 준비하는 프로젝트. 기술적 취약점 점검과 감사 대응 자료 준비를 통해 심사를 통과하는 것이 목표.', 0, '2026-07-01 09:00:00', '2026-08-06 18:00:00'),
(9, '판교 DC 이중화 2단계', 'ONGOING', '2026-02-02', '2026-12-31', 600000000, '1단계에서 구축한 서버·스토리지 이중화를 네트워크·전원 계열까지 확장하는 후속 프로젝트. 데이터센터 장애가 발생해도 서비스가 끊기지 않는 완전 무중단 체계를 갖추는 것이 목표.', 0, '2026-02-02 09:00:00', '2026-08-06 18:00:00'),
(10, '판교 DC 이중화 1단계', 'COMPLETED', '2024-02-01', '2024-09-30', 550000000, '판교 데이터센터에 단일 장애점(SPOF)이 다수 존재한다는 내부 진단에 따라 착수한 1단계 이중화 프로젝트. 서버·스토리지를 이중화해 기본적인 무중단 운영 기반을 마련하는 것이 목표였다.', 0, '2024-02-01 09:00:00', '2024-09-30 18:00:00'),
(11, '그룹 통합인증(SSO) 프로젝트', 'COMPLETED', '2024-03-01', '2024-08-31', 300000000, '다온뱅크·다온증권·다온페이 각 서비스마다 로그인을 따로 해야 하는 불편이 그룹 차원의 개선 과제로 채택돼 착수. 한 번의 로그인으로 그룹 전 서비스를 이용할 수 있는 통합 인증(SSO) 체계를 구축하는 것이 목표였다.', 0, '2024-03-01 09:00:00', '2024-08-31 18:00:00'),
(12, '동해저축은행 여신관리 시스템 구축', 'COMPLETED', '2024-09-01', '2025-03-31', 350000000, '동해저축은행의 여신관리 시스템 노후화에 따라 전면 재구축을 의뢰받아 수주. 여신 심사부터 사후관리까지 전 과정을 시스템화하는 것이 목표였다.', 0, '2024-09-01 09:00:00', '2025-03-31 18:00:00'),
(13, '다온증권 MTS 리뉴얼 1차', 'COMPLETED', '2024-11-01', '2025-06-30', 500000000, '다온증권 MTS(모바일트레이딩시스템)의 UI/UX가 노후화됐다는 고객 피드백이 누적돼 착수한 1차 리뉴얼 프로젝트. 사용성 개선과 함께, 이후 다른 서비스에도 재사용할 수 있는 디자인시스템 기반을 마련하는 것이 목표였다.', 0, '2024-11-01 09:00:00', '2025-06-30 18:00:00'),
(14, 'FDS 엔진 v2', 'COMPLETED', '2025-01-01', '2025-12-31', 300000000, '1세대 FDS 엔진의 탐지 성능에 한계가 있다는 내부 평가에 따라 착수한 2세대 개발 프로젝트. 머신러닝 기반 이상거래 탐지 모델을 도입해 탐지 정확도를 높이는 것이 목표였다.', 0, '2025-01-01 09:00:00', '2025-12-31 18:00:00'),
(15, '다온뱅크 이체 지연 긴급 대응', 'COMPLETED', '2024-11-15', '2024-11-20', 20000000, '다온뱅크 이체 서비스에서 지연 장애가 발생해 긴급 편성된 대응 프로젝트. 원인 분석과 즉시 복구, 재발 방지 조치를 완료하는 것이 목표였다.', 0, '2024-11-15 09:00:00', '2024-11-20 18:00:00');
INSERT INTO projects (id, name, status, start_date, target_date, target_budget, description, version, created_at, modified_at) VALUES
(16, '레거시 API 정리', 'COMPLETED', '2024-04-01', '2024-08-15', 60000000, '이전 시스템에서 넘어온 API가 문서화도 안 된 채 방치돼 있어 유지보수 부담이 컸다. 사용 빈도가 낮은 API를 정리하고 남은 API는 문서화를 완료하는 것이 목표.', 0, '2024-04-01 09:00:00', '2024-08-15 18:00:00'),
(17, '배치 작업 모니터링 고도화', 'COMPLETED', '2024-05-01', '2024-09-10', 70000000, '배치 실패를 담당자가 아침에야 알게 되는 경우가 잦았다. 실패 즉시 알림이 가도록 모니터링 체계를 개선하는 것이 목표.', 0, '2024-05-01 09:00:00', '2024-09-10 18:00:00'),
(18, '인증 토큰 정책 개선', 'COMPLETED', '2024-06-01', '2024-10-15', 65000000, '토큰 만료 정책이 서비스마다 달라 사용자 불편이 있었다. 정책을 통일하고 갱신 로직을 개선하는 것이 목표.', 0, '2024-06-01 09:00:00', '2024-10-15 18:00:00'),
(19, '그룹 채널 연동 안정화', 'COMPLETED', '2024-08-01', '2025-01-20', 90000000, '외부 채널 연동이 간헐적으로 끊기는 문제가 반복 보고됐다. 재시도 로직과 장애 감지를 보강하는 것이 목표.', 0, '2024-08-01 09:00:00', '2025-01-20 18:00:00'),
(20, '코드 리뷰 프로세스 개선 TF', 'COMPLETED', '2024-09-01', '2024-11-10', 30000000, '파트별로 리뷰 기준이 달라 품질 편차가 있었다. 공통 체크리스트를 만들어 리뷰 품질을 표준화하는 것이 목표.', 0, '2024-09-01 09:00:00', '2024-11-10 18:00:00'),
(21, '결제 시스템 성능 개선', 'COMPLETED', '2025-01-06', '2025-05-20', 110000000, '결제 처리 지연이 트래픽 몰릴 때 반복됐다. 병목 구간을 찾아 응답 시간을 단축하는 것이 목표.', 0, '2025-01-06 09:00:00', '2025-05-20 18:00:00'),
(22, 'DB 인덱스 정비', 'COMPLETED', '2025-02-03', '2025-04-15', 50000000, '쿼리 성능이 서비스 성장에 따라 저하되고 있었다. 인덱스를 재설계해 조회 성능을 개선하는 것이 목표.', 0, '2025-02-03 09:00:00', '2025-04-15 18:00:00'),
(23, '그룹 인증 로그 표준화', 'COMPLETED', '2025-05-01', '2025-08-15', 55000000, '감사 대응 시 로그 포맷이 시스템마다 달라 집계에 시간이 걸렸다. 로그 포맷을 통일해 감사 대응 효율을 높이는 것이 목표.', 0, '2025-05-01 09:00:00', '2025-08-15 18:00:00'),
(24, 'API 게이트웨이 1차 구축', 'COMPLETED', '2025-06-02', '2025-11-14', 150000000, '서비스별 API가 개별 관리돼 트래픽 통제가 어려웠다. 게이트웨이를 도입해 트래픽을 일원화하는 것이 목표.', 0, '2025-06-02 09:00:00', '2025-11-14 18:00:00'),
(25, '코어뱅킹 배치 리팩토링', 'COMPLETED', '2025-09-01', '2026-01-20', 120000000, '오래된 배치 코드가 신규 개발자에게 진입장벽이 됐다. 구조를 정리해 유지보수성을 높이는 것이 목표.', 0, '2025-09-01 09:00:00', '2026-01-20 18:00:00'),
(26, '장애 대응 매뉴얼 정비', 'COMPLETED', '2026-01-05', '2026-03-10', 25000000, '장애 대응 절차가 개인 경험에 의존해 신입 대응이 늦었다. 표준 매뉴얼을 만들어 대응 속도를 높이는 것이 목표.', 0, '2026-01-05 09:00:00', '2026-03-10 18:00:00'),
(27, '테스트 커버리지 확대 TF', 'DROPPED', '2025-03-03', '2025-06-01', 40000000, '핵심 모듈의 테스트 커버리지가 낮아 배포 시 불안 요소가 있었다. 우선순위가 높은 다른 프로젝트에 인력이 재배치되며 중단됐다.', 0, '2025-03-03 09:00:00', '2025-06-01 18:00:00'),
(28, '컴포넌트 라이브러리 v1 구축', 'COMPLETED', '2024-01-15', '2024-04-20', 80000000, '화면마다 버튼·인풋 스타일이 제각각이라 일관성이 없었다. 공통 컴포넌트를 만들어 개발 속도와 디자인 일관성을 높이는 것이 목표.', 0, '2024-01-15 09:00:00', '2024-04-20 18:00:00'),
(29, '모바일 반응형 개선', 'COMPLETED', '2024-05-01', '2024-08-15', 60000000, '모바일 브라우저 접속 시 레이아웃이 깨지는 문제가 잦았다. 반응형 대응을 정비해 모바일 사용성을 높이는 것이 목표.', 0, '2024-05-01 09:00:00', '2024-08-15 18:00:00'),
(30, '접근성(a11y) 1차 개선', 'COMPLETED', '2024-09-02', '2024-12-13', 55000000, '스크린리더 사용자 대상 접근성 점검에서 다수 이슈가 발견됐다. 주요 화면부터 접근성 기준을 충족시키는 것이 목표.', 0, '2024-09-02 09:00:00', '2024-12-13 18:00:00'),
(31, '번들 사이즈 최적화', 'COMPLETED', '2025-01-06', '2025-03-14', 35000000, '초기 로딩 속도가 느리다는 사용자 피드백이 있었다. 불필요한 의존성을 정리해 번들 크기를 줄이는 것이 목표.', 0, '2025-01-06 09:00:00', '2025-03-14 18:00:00'),
(32, '다크모드 지원', 'COMPLETED', '2025-04-01', '2025-06-13', 45000000, '사내 시스템에 다크모드가 없어 야간 근무자 불편이 있었다. 전 화면에 다크모드를 지원하는 것이 목표.', 0, '2025-04-01 09:00:00', '2025-06-13 18:00:00'),
(33, '차트 라이브러리 통일', 'COMPLETED', '2025-07-01', '2025-09-12', 40000000, '서비스마다 다른 차트 라이브러리를 써서 유지보수가 분산됐다. 하나로 통일해 관리 포인트를 줄이는 것이 목표.', 0, '2025-07-01 09:00:00', '2025-09-12 18:00:00'),
(34, '레거시 jQuery 코드 제거', 'HOLDING', '2025-10-06', '2026-06-30', 70000000, '일부 오래된 화면에 jQuery 코드가 남아 있어 신규 스택과 혼재됐다. 전환 우선순위가 밀리며 잠정 보류 중이다.', 0, '2025-10-06 09:00:00', '2026-08-06 18:00:00'),
(35, '웹 접근성 2차 개선', 'COMPLETED', '2026-02-02', '2026-05-15', 50000000, '1차 개선 이후에도 남은 접근성 이슈가 감사에서 재지적됐다. 나머지 화면까지 접근성 기준을 완전히 충족시키는 것이 목표.', 0, '2026-02-02 09:00:00', '2026-05-15 18:00:00'),
(36, '테스트 자동화 도입 TF', 'COMPLETED', '2024-04-01', '2024-07-12', 50000000, '회귀 테스트를 매번 수작업으로 반복해 릴리즈마다 시간이 오래 걸렸다. 핵심 시나리오부터 자동화해 릴리즈 속도를 높이는 것이 목표.', 0, '2024-04-01 09:00:00', '2024-07-12 18:00:00'),
(37, '버그 트래킹 프로세스 정비', 'COMPLETED', '2024-08-01', '2024-10-11', 20000000, '버그 재현 정보가 부실해 개발팀과의 커뮤니케이션 비용이 컸다. 리포트 템플릿을 표준화해 커뮤니케이션을 줄이는 것이 목표.', 0, '2024-08-01 09:00:00', '2024-10-11 18:00:00'),
(38, '성능 테스트 환경 구축', 'COMPLETED', '2025-01-06', '2025-04-18', 65000000, '성능 이슈를 실서비스에서야 발견하는 경우가 있었다. 별도 성능 테스트 환경을 구축해 사전 검증을 강화하는 것이 목표.', 0, '2025-01-06 09:00:00', '2025-04-18 18:00:00'),
(39, 'QA 온보딩 가이드 제작', 'COMPLETED', '2025-06-02', '2025-07-11', 15000000, '신입 QA가 프로젝트별 컨벤션을 파악하는 데 시간이 오래 걸렸다. 온보딩 가이드를 만들어 적응 기간을 줄이는 것이 목표.', 0, '2025-06-02 09:00:00', '2025-07-11 18:00:00'),
(40, '모바일 앱 QA 체계 수립', 'COMPLETED', '2025-09-01', '2025-12-12', 60000000, '모바일 앱 출시가 늘며 기존 웹 중심 QA 체계로는 대응이 부족했다. 모바일 전용 테스트 체계를 수립하는 것이 목표.', 0, '2025-09-01 09:00:00', '2025-12-12 18:00:00'),
(41, 'QA 자동화 커버리지 확대 2차', 'COMPLETED', '2026-01-05', '2026-04-16', 55000000, '1차 자동화 이후에도 수작업 비중이 여전히 높았다. 회귀 테스트의 자동화 비율을 추가로 끌어올리는 것이 목표.', 0, '2026-01-05 09:00:00', '2026-04-16 18:00:00'),
(42, 'CI 파이프라인 표준화', 'COMPLETED', '2024-04-01', '2024-07-11', 55000000, '팀마다 CI 설정이 달라 신규 서비스 추가 시마다 새로 세팅해야 했다. 공통 템플릿을 만들어 설정 시간을 줄이는 것이 목표.', 0, '2024-04-01 09:00:00', '2024-07-11 18:00:00'),
(43, '배포 롤백 자동화', 'COMPLETED', '2024-08-01', '2024-11-14', 60000000, '배포 실패 시 수작업 롤백에 시간이 걸려 장애 시간이 길어졌다. 롤백을 자동화해 복구 시간을 단축하는 것이 목표.', 0, '2024-08-01 09:00:00', '2024-11-14 18:00:00'),
(44, '클라우드 비용 1차 최적화', 'COMPLETED', '2025-01-06', '2025-03-14', 30000000, '사용하지 않는 리소스가 방치돼 비용이 새고 있다는 지적이 있었다. 유휴 리소스를 정리해 비용을 절감하는 것이 목표.', 0, '2025-01-06 09:00:00', '2025-03-14 18:00:00'),
(45, '컨테이너 오케스트레이션 전환', 'COMPLETED', '2025-04-01', '2025-10-17', 180000000, '기존 배포 방식으로는 트래픽 증가에 유연하게 대응하기 어려웠다. 컨테이너 기반으로 전환해 확장성을 확보하는 것이 목표.', 0, '2025-04-01 09:00:00', '2025-10-17 18:00:00'),
(46, '장애 알림 채널 통합', 'COMPLETED', '2025-11-03', '2026-01-16', 25000000, '장애 알림이 여러 채널에 흩어져 있어 초기 대응이 늦어지는 경우가 있었다. 알림을 한 채널로 통합해 대응 속도를 높이는 것이 목표.', 0, '2025-11-03 09:00:00', '2026-01-16 18:00:00'),
(47, '카오스 엔지니어링 도입 검토', 'HOLDING', '2026-03-02', '2026-06-30', 20000000, '장애 대응력을 사전에 검증할 방법이 필요하다는 논의가 있었다. 우선순위 조정으로 본 착수는 잠정 보류 중이다.', 0, '2026-03-02 09:00:00', '2026-08-06 18:00:00'),
(48, '네트워크 회선 이중화 점검', 'COMPLETED', '2024-04-01', '2024-06-14', 40000000, '회선 단일 장애점이 남아있는지 전수 점검이 필요했다. 이중화 누락 구간을 찾아 보완하는 것이 목표.', 0, '2024-04-01 09:00:00', '2024-06-14 18:00:00'),
(49, '서버 자산 관리 체계 정비', 'COMPLETED', '2024-07-01', '2024-09-13', 30000000, '서버 자산 현황이 문서와 실제가 어긋나는 경우가 많았다. 자산 관리 대장을 실사와 맞춰 정비하는 것이 목표.', 0, '2024-07-01 09:00:00', '2024-09-13 18:00:00'),
(50, '재해복구(DR) 훈련 1차', 'COMPLETED', '2025-01-13', '2025-02-14', 20000000, '재해복구 절차가 문서로만 있고 실제 검증된 적이 없었다. 모의 훈련을 통해 절차의 실효성을 검증하는 것이 목표.', 0, '2025-01-13 09:00:00', '2025-02-14 18:00:00'),
(51, '전력 계통 정기 점검', 'COMPLETED', '2025-05-05', '2025-06-13', 15000000, '전력 설비 노후화에 따른 사전 점검 필요성이 제기됐다. 정기 점검을 통해 잠재 위험을 사전에 제거하는 것이 목표.', 0, '2025-05-05 09:00:00', '2025-06-13 18:00:00'),
(52, 'IDC 온도·습도 모니터링 고도화', 'COMPLETED', '2025-09-01', '2025-11-14', 35000000, '기존 센서로는 이상 징후를 늦게 감지하는 문제가 있었다. 센서를 추가하고 임계치 알림을 정교화하는 것이 목표.', 0, '2025-09-01 09:00:00', '2025-11-14 18:00:00'),
(53, '재해복구(DR) 훈련 2차', 'COMPLETED', '2026-04-06', '2026-05-15', 20000000, '1차 훈련에서 발견된 미비점 보완 여부를 재검증할 필요가 있었다. 개선된 절차로 2차 모의 훈련을 진행하는 것이 목표.', 0, '2026-04-06 09:00:00', '2026-05-15 18:00:00'),
(54, '그룹사 데이터 표준 용어집 구축', 'COMPLETED', '2024-04-01', '2024-07-12', 40000000, '부서마다 같은 지표를 다른 용어로 불러 데이터 해석에 혼선이 있었다. 표준 용어집을 만들어 커뮤니케이션 혼선을 줄이는 것이 목표.', 0, '2024-04-01 09:00:00', '2024-07-12 18:00:00'),
(55, '데이터 파이프라인 모니터링 고도화', 'COMPLETED', '2024-08-01', '2024-11-15', 50000000, '파이프라인 실패를 다음 날에야 발견하는 경우가 있었다. 실시간 모니터링을 도입해 발견 시간을 단축하는 것이 목표.', 0, '2024-08-01 09:00:00', '2024-11-15 18:00:00'),
(56, '그룹사 리포팅 자동화 1차', 'COMPLETED', '2025-01-06', '2025-04-18', 70000000, '정기 리포트를 매번 수작업으로 취합해 시간이 오래 걸렸다. 자동 취합 체계를 구축해 작업 시간을 줄이는 것이 목표.', 0, '2025-01-06 09:00:00', '2025-04-18 18:00:00'),
(57, '데이터 거버넌스 정책 수립', 'COMPLETED', '2025-05-01', '2025-08-15', 45000000, '데이터 접근 권한 기준이 명확하지 않아 관리가 느슨했다. 접근 권한 정책을 문서화하고 체계를 잡는 것이 목표.', 0, '2025-05-01 09:00:00', '2025-08-15 18:00:00'),
(58, '마이데이터 2.0 대응', 'COMPLETED', '2025-09-01', '2025-12-12', 90000000, '마이데이터 2.0 규격 시행에 따라 기존 연동 모듈 수정이 필요했다. 신규 규격에 맞춰 연동 모듈을 개선하는 것이 목표.', 0, '2025-09-01 09:00:00', '2025-12-12 18:00:00'),
(59, '데이터 품질 점검 자동화', 'COMPLETED', '2026-01-05', '2026-03-13', 40000000, '데이터 품질 이슈를 리포트 배포 후에야 발견하는 경우가 있었다. 사전 검증 로직을 자동화해 배포 전에 걸러내는 것이 목표.', 0, '2026-01-05 09:00:00', '2026-03-13 18:00:00'),
(60, '접근권한 재정비 TF', 'COMPLETED', '2024-04-01', '2024-06-14', 30000000, '퇴사자·부서이동자의 권한이 제때 회수되지 않는 사례가 발견됐다. 권한 부여·회수 프로세스를 재정비하는 것이 목표.', 0, '2024-04-01 09:00:00', '2024-06-14 18:00:00'),
(61, '취약점 점검 자동화', 'COMPLETED', '2024-09-02', '2024-11-15', 45000000, '수동 취약점 점검으로는 신규 배포마다 대응이 늦었다. 정기 스캔을 자동화해 점검 주기를 단축하는 것이 목표.', 0, '2024-09-02 09:00:00', '2024-11-15 18:00:00'),
(62, '개인정보 암호화 적용 확대', 'COMPLETED', '2025-02-03', '2025-05-16', 60000000, '일부 레거시 테이블에 암호화가 누락돼 있다는 점검 결과가 나왔다. 대상 테이블 전체에 암호화를 적용하는 것이 목표.', 0, '2025-02-03 09:00:00', '2025-05-16 18:00:00'),
(63, '모의해킹 대응', 'COMPLETED', '2025-07-01', '2025-08-15', 25000000, '연례 모의해킹에서 발견된 취약점에 대한 후속 조치가 필요했다. 지적된 항목을 조치하고 재검증받는 것이 목표.', 0, '2025-07-01 09:00:00', '2025-08-15 18:00:00'),
(64, 'ISMS-P 사전 점검 TF', 'COMPLETED', '2026-04-06', '2026-06-12', 30000000, '정식 인증 갱신 심사 전에 내부적으로 미비점을 먼저 걸러낼 필요가 있었다. 사전 점검을 통해 본 심사 통과 가능성을 높이는 것이 목표.', 0, '2026-04-06 09:00:00', '2026-06-12 18:00:00'),
(65, '프로젝트 리소스 배분 도구 도입', 'COMPLETED', '2024-04-01', '2024-06-14', 20000000, '여러 프로젝트에 걸친 인력 배분 현황을 한눈에 보기 어려웠다. 배분 현황을 시각화하는 도구를 도입하는 것이 목표.', 0, '2024-04-01 09:00:00', '2024-06-14 18:00:00'),
(66, 'PM 온보딩 가이드 제작', 'COMPLETED', '2024-09-02', '2024-10-11', 10000000, '신규 PM이 사내 프로젝트 관행을 파악하는 데 시간이 걸렸다. 온보딩 가이드를 만들어 적응 기간을 줄이는 것이 목표.', 0, '2024-09-02 09:00:00', '2024-10-11 18:00:00'),
(67, '대외 프로젝트 계약 관리 표준화', 'COMPLETED', '2025-02-03', '2025-04-11', 25000000, '대외 프로젝트 계약 조건 변경 이력 관리가 개인별로 제각각이었다. 표준 양식을 도입해 관리 일관성을 높이는 것이 목표.', 0, '2025-02-03 09:00:00', '2025-04-11 18:00:00'),
(68, '프로젝트 정기 보고 템플릿 개선', 'COMPLETED', '2025-08-04', '2025-09-12', 10000000, '프로젝트별 보고 형식이 달라 경영진 취합에 시간이 걸렸다. 공통 템플릿으로 통일해 취합 효율을 높이는 것이 목표.', 0, '2025-08-04 09:00:00', '2025-09-12 18:00:00'),
(69, '리소스 배분 도구 2차 고도화', 'ARCHIVED', '2026-01-05', '2026-02-13', 15000000, '1차 도구의 활용도가 낮아 개선을 시도했으나, 상위 도구(PrettyWorks) 도입 결정으로 중단됐다.', 0, '2026-01-05 09:00:00', '2026-02-13 18:00:00'),
(70, '제안서 템플릿 표준화', 'COMPLETED', '2024-04-01', '2024-06-14', 20000000, '제안서마다 구성과 톤이 달라 품질 편차가 있었다. 표준 템플릿을 만들어 제안서 품질을 균일화하는 것이 목표.', 0, '2024-04-01 09:00:00', '2024-06-14 18:00:00'),
(71, '금융권 규제 동향 스터디', 'COMPLETED', '2024-07-01', '2024-09-12', 15000000, '대외 컨설팅 시 최신 규제 동향 파악이 개인 역량에 의존했다. 정기 스터디 체계를 만들어 팀 전체 대응력을 높이는 것이 목표.', 0, '2024-07-01 09:00:00', '2024-09-12 18:00:00'),
(72, '대외 상주 인력 지원 체계 정비', 'COMPLETED', '2025-01-06', '2025-03-14', 20000000, '상주 인력이 본사 지원을 받기까지 시간이 걸린다는 불만이 있었다. 전담 지원 채널을 만들어 응답 속도를 높이는 것이 목표.', 0, '2025-01-06 09:00:00', '2025-03-14 18:00:00'),
(73, '코어뱅킹 아키텍처 컨설팅 방법론 정리', 'COMPLETED', '2025-06-02', '2025-09-12', 40000000, '프로젝트마다 접근 방식이 달라 산출물 품질 편차가 있었다. 표준 방법론을 정리해 프로젝트 간 일관성을 높이는 것이 목표.', 0, '2025-06-02 09:00:00', '2025-09-12 18:00:00'),
(74, '저축은행권 영업 자료 리뉴얼', 'COMPLETED', '2025-10-06', '2025-11-14', 10000000, '기존 영업 자료가 최신 사업 실적을 반영하지 못하고 있었다. 최신 레퍼런스를 반영해 자료를 갱신하는 것이 목표.', 0, '2025-10-06 09:00:00', '2025-11-14 18:00:00'),
(75, '대외 프로젝트 리스크 관리 체계 수립', 'DROPPED', '2026-01-05', '2026-03-13', 25000000, '프로젝트별 리스크를 조기에 식별할 체계가 필요하다는 문제 제기가 있었다. 담당자 공백으로 착수 직후 중단됐다.', 0, '2026-01-05 09:00:00', '2026-03-13 18:00:00'),
(76, '그룹사 영업 채널 데이터 정리', 'COMPLETED', '2024-04-01', '2024-06-14', 15000000, '그룹사별 담당자 연락 이력이 개인 수첩·메일에만 흩어져 있었다. 데이터를 한곳에 정리해 인수인계 부담을 줄이는 것이 목표.', 0, '2024-04-01 09:00:00', '2024-06-14 18:00:00'),
(77, '대외 영업 파이프라인 관리 체계 도입', 'COMPLETED', '2024-10-07', '2024-12-13', 25000000, '영업 기회 현황을 파악할 공통 도구가 없어 진행 상황이 불투명했다. 파이프라인 관리 체계를 도입해 가시성을 높이는 것이 목표.', 0, '2024-10-07 09:00:00', '2024-12-13 18:00:00'),
(78, '그룹사 계약 갱신 프로세스 정비', 'COMPLETED', '2025-04-07', '2025-06-13', 15000000, '계약 갱신 시점을 놓쳐 뒤늦게 대응하는 경우가 있었다. 갱신 일정을 사전에 관리하는 체계를 만드는 것이 목표.', 0, '2025-04-07 09:00:00', '2025-06-13 18:00:00'),
(79, '신규 대외 고객사 발굴 전략 수립', 'COMPLETED', '2025-11-03', '2026-01-16', 20000000, '기존 대외 고객사 편중으로 신규 채널 확보 필요성이 제기됐다. 신규 고객군을 발굴하는 전략을 수립하는 것이 목표.', 0, '2025-11-03 09:00:00', '2026-01-16 18:00:00'),
(80, '신규 상품 타당성 검토 TF', 'COMPLETED', '2024-05-02', '2024-07-12', 20000000, '신규 금융 상품 아이디어의 사업성을 체계적으로 검증할 절차가 없었다. 타당성 검토 프레임을 만들어 의사결정을 지원하는 것이 목표.', 0, '2024-05-02 09:00:00', '2024-07-12 18:00:00'),
(81, '사업계획 수립 프로세스 개선', 'COMPLETED', '2024-11-04', '2024-12-13', 10000000, '연간 사업계획 수립이 부서마다 다른 양식과 일정으로 진행돼 취합이 어려웠다. 공통 프로세스를 정립해 취합 효율을 높이는 것이 목표.', 0, '2024-11-04 09:00:00', '2024-12-13 18:00:00'),
(82, '그룹사 시너지 과제 발굴', 'COMPLETED', '2025-05-05', '2025-07-11', 20000000, '그룹사 간 협업 기회가 있어도 파악할 통로가 없었다. 부서 간 시너지 과제를 발굴하는 것이 목표.', 0, '2025-05-05 09:00:00', '2025-07-11 18:00:00'),
(83, '경쟁사 벤치마킹 리포트', 'COMPLETED', '2026-01-05', '2026-02-13', 10000000, '경쟁 금융 IT 자회사들의 동향을 정기적으로 파악할 필요가 있었다. 벤치마킹 리포트를 작성해 전략 수립에 참고하는 것이 목표.', 0, '2026-01-05 09:00:00', '2026-02-13 18:00:00'),
(84, '사내 규정집 전면 개정', 'COMPLETED', '2024-04-01', '2024-07-12', 20000000, '조직이 커지며 기존 규정이 실제 운영과 안 맞는 부분이 늘었다. 규정을 현행화해 실무 혼선을 줄이는 것이 목표.', 0, '2024-04-01 09:00:00', '2024-07-12 18:00:00'),
(85, '총무 자산 관리 시스템 정비', 'COMPLETED', '2024-09-02', '2024-11-15', 25000000, '사무기기·비품 관리가 수기 대장으로 이뤄져 누락이 잦았다. 관리 체계를 정비해 자산 파악을 정확하게 하는 것이 목표.', 0, '2024-09-02 09:00:00', '2024-11-15 18:00:00'),
(86, '법무 계약서 검토 프로세스 표준화', 'COMPLETED', '2025-03-03', '2025-05-16', 15000000, '계약서 검토 기준이 담당자마다 달라 처리 속도 편차가 있었다. 표준 체크리스트를 만들어 검토 속도를 높이는 것이 목표.', 0, '2025-03-03 09:00:00', '2025-05-16 18:00:00'),
(87, '사내 준법 교육 체계 개편', 'COMPLETED', '2025-09-01', '2025-10-17', 10000000, '준법 교육이 형식적으로 진행돼 실효성 지적이 있었다. 실무 사례 중심으로 교육 내용을 개편하는 것이 목표.', 0, '2025-09-01 09:00:00', '2025-10-17 18:00:00'),
(88, '채용 프로세스 개선 TF', 'COMPLETED', '2024-05-02', '2024-07-12', 15000000, '채용 단계별 소요 기간이 길어 우수 인재를 놓치는 경우가 있었다. 프로세스를 간소화해 채용 기간을 단축하는 것이 목표.', 0, '2024-05-02 09:00:00', '2024-07-12 18:00:00'),
(89, '온보딩 프로그램 개편', 'COMPLETED', '2025-01-06', '2025-03-14', 10000000, '신입 정착률이 기대에 못 미친다는 문제 제기가 있었다. 온보딩 프로그램을 개편해 초기 적응을 돕는 것이 목표.', 0, '2025-01-06 09:00:00', '2025-03-14 18:00:00'),
(90, '평가 제도 개선 TF', 'COMPLETED', '2025-10-06', '2025-12-12', 15000000, '평가 기준이 부서마다 다르게 적용된다는 불만이 반복 제기됐다. 평가 기준을 표준화해 공정성 시비를 줄이는 것이 목표.', 0, '2025-10-06 09:00:00', '2025-12-12 18:00:00'),
(91, '결산 프로세스 자동화', 'COMPLETED', '2024-06-03', '2024-09-13', 30000000, '월별 결산에 수작업 집계가 많아 마감까지 시간이 오래 걸렸다. 집계 과정을 자동화해 결산 소요 시간을 줄이는 것이 목표.', 0, '2024-06-03 09:00:00', '2024-09-13 18:00:00'),
(92, '프로젝트별 원가 관리 체계 고도화', 'COMPLETED', '2025-02-03', '2025-05-16', 35000000, '프로젝트 수익성 파악이 결산 시점에야 가능해 실시간 대응이 어려웠다. 원가 관리 체계를 고도화해 상시 파악이 가능하게 하는 것이 목표.', 0, '2025-02-03 09:00:00', '2025-05-16 18:00:00'),
(93, '지출 결의 정합성 점검 자동화', 'COMPLETED', '2026-02-02', '2026-04-17', 20000000, '지출 결의 데이터의 오류를 사후 감사에서야 발견하는 경우가 있었다. 사전 검증 로직을 자동화해 오류를 미리 걸러내는 것이 목표.', 0, '2026-02-02 09:00:00', '2026-04-17 18:00:00');
